param(\n  [string]$Url = "http://servidor-interno:8080",\n  [string]$Nome = "Escala TJCE - Férias"\n)\n\n$ErrorActionPreference = "Stop"\n$desktop = [Environment]::GetFolderPath("Desktop")\n$scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path\n$iconPath = Join-Path $scriptDir "escala-tjce.ico"\n$shortcutPath = Join-Path $desktop ($Nome + ".lnk")\n\n$browser = "$env:ProgramFiles\\Google\\Chrome\\Application\\chrome.exe"\nif (-not (Test-Path $browser)) { $browser = "$env:ProgramFiles(x86)\\Microsoft\\Edge\\Application\\msedge.exe" }\nif (-not (Test-Path $browser)) { $browser = "$env:SystemRoot\\System32\\cmd.exe" }\n\n$shell = New-Object -ComObject WScript.Shell\n$shortcut = $shell.CreateShortcut($shortcutPath)\nif ($browser -like "*cmd.exe") {\n  $shortcut.TargetPath = $browser\n  $shortcut.Arguments = "/c start \"\" \"" + $Url + "\""\n} else {\n  $shortcut.TargetPath = $browser\n  $shortcut.Arguments = $Url\n}\n$shortcut.WorkingDirectory = $scriptDir\n$shortcut.Description = "Acesso ao sistema Escala TJCE - Férias e Rodízio"\nif (Test-Path $iconPath) { $shortcut.IconLocation = "$iconPath,0" }\n$shortcut.Save()\nWrite-Host ""\nWrite-Host "Atalho criado com sucesso:" -ForegroundColor Green\nWrite-Host $shortcutPath\nWrite-Host "Destino: $Url"\n